import type { ReactNode } from "react"
import { Button } from "@/shared/ui/button"
import { SparklesIcon } from "@/shared/ui/icon"

/**
 * 데스크톱 화면 아래 40px 줄(AppShell의 bottomBar, 화면 폭 전체). 오른쪽 끝에 에이전트를 여는 조용한 단추(보조 글자색),
 * 앱이 넣는 것(바코드 장식 · 상태)은 그 단추 바로 왼쪽에 붙는다.
 * 휴대폰에는 두지 않는다(하단 탭 자리다).
 */
export function AgentBar({ label = "Agent", onOpen, start, children }: {
  label?: string; onOpen?: () => void
  /** 줄 왼쪽 끝(앱의 버전 같은 조용한 정보). */
  start?: ReactNode
  children?: ReactNode
}) {
  return (
    <div className="flex h-10 shrink-0 items-center justify-end gap-2 px-3">
      {start && <div className="mr-auto flex min-w-0 items-center gap-2 pl-2 text-xs text-muted-foreground">{start}</div>}
      {children && <div className="flex min-w-0 items-center gap-2 text-xs text-muted-foreground">{children}</div>}
      <Button variant="ghost" size="sm" className="text-muted-foreground" onClick={onOpen}>
        <SparklesIcon data-icon="inline-start" />
        {label}
      </Button>
    </div>
  )
}

import { useMemo, useState, type CSSProperties, type ReactNode } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { cn } from "cn"
import { PageChromeProvider } from "@/shared/ui/layout/page"
import { SidebarProvider, useSidebar } from "@/shared/ui/sidebar"
import { Button } from "@/shared/ui/button"
import { PanelLeftIcon } from "@/shared/ui/icon"
import { TooltipProvider } from "@/shared/ui/tooltip"
import { MeButton, type ShellMe } from "./MeMenu"
import { MobileTabBar } from "./MobileTabBar"
import { PhoneBar, type PhoneBarProps } from "./PhoneBar"
import { currentEntry, type NavEntry, type NavSpace } from "./nav"
import { ShellSidebar, type FoldSlot, type OpenGroups, type ShellLayout } from "./ShellSidebar"
import { SidebarResizeHandle, type HandleEdge } from "./SidebarResizeHandle"

/** 사이드바 너비(루트 16px 기준 px): 처음과 다시 펼칠 때 initial, 끌어서 min~max. */
export type SidebarWidth = { initial: number; min: number; max: number }
const SIDEBAR_WIDTH: SidebarWidth = { initial: 340, min: 220, max: 380 }

export type AppShellProps = {
  /** 지금 주소의 메뉴 한 벌(주 메뉴 또는 하위 공간). 앱이 주소로 고른다. */
  space: NavSpace
  /** 지금 주소. 지금 항목을 찾고, 바뀌면 더보기를 닫는다. */
  pathname: string
  /** 사이드바 머리 왼쪽: 정사각 로고 마크(홈 링크)와 공간 전환 셀렉터(지금 공간의 아이콘 · 이름 · ⇕). 접힌 사이드바는 마크만. */
  brand: FoldSlot
  /** 사이드바 머리 줄 오른쪽: 내 아바타(내 메뉴, MeButton). */
  headerTools?: ReactNode
  /** 내 박스 · 아바타와 내 메뉴. 휴대폰은 앱 바 끝의 아바타. */
  me?: ShellMe
  /** 사이드바 바닥 왼쪽(릴리스 · 환경 설정). */
  footer?: FoldSlot
  /** 데스크톱 본문 아래 줄(AgentBar). inset에서는 본문 면 아래, split에서는 본문 아래 끝에 붙는다. */
  bottomBar?: ReactNode
  /** 휴대폰 앱 바 오른쪽 공통 도구(검색 · 알림함). 내 아바타는 me가 있으면 끝에 붙는다. */
  phoneTools?: ReactNode
  /** 휴대폰 하단 탭. 없으면 공간 메뉴의 앞 네 곳(isPhoneHidden 제외). */
  tabs?: NavEntry[]
  /** inset: 바닥 위에 떠 있는 둥근 본문 면. split: 가는 선으로 나눈 평평한 면. */
  layout?: ShellLayout
  openGroups?: OpenGroups
  sidebarWidth?: SidebarWidth
  /** 사이드바 머리 아래에 내 박스를 둔다(기본). 앱이 머리 도구(headerTools)에 내 아바타를 따로 두면 false. */
  hasMeBox?: boolean
  /** 사이드바 맨 아래 관리 진입: 그 공간의 관리 화면처럼 권한이 있을 때만 준다. */
  adminEntries?: NavEntry[]
  /** 휴대폰 하단을 떠 있는 유리 막대(앞 칸 + 메뉴 시트 칸 + 검색 원)로 둔다. 주지 않으면 하단 탭. */
  phoneBar?: Omit<PhoneBarProps, "current" | "pathname">
  /** 페이지(라우터의 Outlet). */
  children: ReactNode
}

/**
 * 앱 셸. 메뉴는 데이터(space)로 받고, 로고 · 나 · 도구 · 바닥 줄은 자리로 받는다.
 * - 데스크톱: 끌어 220~380px로 바꾸는 사이드바(접으면 아이콘만, 다시 펼치면 처음 너비)와 본문. inset은 바닥(사이드바 색) 위에
 *   위 · 오른쪽 8px 띄운 초타원 면, split은 선으로 나눈 면이다. Ctrl/⌘+B로도 접는다.
 * - 휴대폰(64rem 미만): 사이드바 없이 본문과 하단 탭(앞 네 곳 + 더보기). 위쪽 52px 앱 바는 Page가 그리고 오른쪽 도구는 여기서 넘긴다.
 *   상세 · 양식 페이지가 전체 화면을 알리면(useFullScreen) 하단 탭을 치운다.
 * 본문의 부모 요소는 분기점 · 배치가 바뀌어도 같은 자리에 같은 종류로 두어, 창을 줄이고 늘려도 작성 중인 페이지가 다시 마운트되지 않는다.
 */
export function AppShell({ space, pathname, brand, headerTools, me, footer, bottomBar, phoneTools, tabs, layout = "inset", openGroups = "all",
  sidebarWidth = SIDEBAR_WIDTH, hasMeBox = true, adminEntries, phoneBar, children }: AppShellProps) {
  const isMobile = useIsMobile()
  const [isFullScreen, setFullScreen] = useState(false)
  const [isOpen, setIsOpen] = useState(true)
  const [width, setWidth] = useState(sidebarWidth.initial)
  const [isResizing, setIsResizing] = useState(false)
  const [edge, setEdge] = useState<HandleEdge>("idle")
  const current = currentEntry(space, pathname)
  // 휴대폰 앱 바에는 내 사진을 두지 않는다. 내 메뉴는 하단 막대의 메뉴 시트 머리에 있다(PhoneBar).
  const tools = useMemo(() => phoneTools ?? null, [phoneTools])
  // 사이드바 접기는 본문 머리 줄 맨 왼쪽(페이지 머리 · 상세 페이지 머리)에 고정한다.
  const sidebarToggle = !isMobile ? <SidebarToggle /> : null
  const chrome = useMemo(() => ({ tools, setFullScreen, sidebarToggle }), [tools, sidebarToggle !== null])
  const open = (next: boolean) => {
    setIsOpen(next)
    if (next) setWidth(sidebarWidth.initial)
  }
  const isInset = layout === "inset"
  const hasPhoneBar = !!phoneBar && isMobile && !isFullScreen
  // 데스크톱 아래 줄(에이전트 줄, 40px)은 화면 폭 전체에 깔리고, 사이드바와 본문 면은 그 위에서 같은 높이로 끝난다.
  const hasBottomBar = !!bottomBar && !isMobile
  return (
    <TooltipProvider>
      <PageChromeProvider value={chrome}>
        {/* check-ui: allow-style 사이드바 너비는 사용자가 끌어 정한 값이다(rem이라 큰 화면의 루트 배율을 따른다). */}
        <SidebarProvider open={isOpen} onOpenChange={open} style={{ "--sidebar-width": `${width / 16}rem`,
          // 휴대폰 유리 막대 몫: 막대(56px) + 아래 띄움(12px) + 홈 표시줄 + 4px. 페이지 본문 · 바닥 줄 · FAB가 이만큼 비운다.
          ...(hasPhoneBar ? { "--phone-bar-space": "calc(4.5rem + env(safe-area-inset-bottom))" } : {}) } as CSSProperties}
          // 끄는 동안에는 너비 전환 애니메이션을 끈다(손을 바로 따라가도록).
          className={cn("h-svh min-h-0 overflow-hidden", isMobile || !isInset ? "bg-background" : "bg-sidebar",
            isResizing && "**:data-[slot=sidebar-container]:transition-none **:data-[slot=sidebar-gap]:transition-none **:data-[slot=shell-brand]:transition-none")}>
          {!isMobile && <ShellSidebar space={space} current={current} brand={brand}
            headerTools={headerTools} me={hasMeBox ? me : undefined} footer={footer} adminEntries={adminEntries}
            layout={layout} openGroups={openGroups} isAboveBar={hasBottomBar} />}
          {!isMobile && isOpen && <SidebarResizeHandle value={width} min={sidebarWidth.min} max={sidebarWidth.max} onChange={setWidth}
            onDraggingChange={setIsResizing} onEdgeChange={isInset ? setEdge : undefined} />}
          <div className={cn("flex min-w-0 flex-1 flex-col", hasBottomBar && "pb-10")}>
            {/* inset: 너비 손잡이를 가리키거나 끌 때 본문 면의 왼쪽 가장자리가 선다(면의 둥근 모서리를 따라 잘린다). */}
            <main data-edge={!isMobile && isInset && isOpen ? edge : undefined}
              className={cn("relative flex min-h-0 flex-1 flex-col overflow-hidden bg-background",
              "before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:z-50 before:w-0 before:bg-transparent before:transition-[width,background-color]",
              "data-[edge=hover]:before:w-0.5 data-[edge=hover]:before:bg-border data-[edge=active]:before:w-1 data-[edge=active]:before:bg-ring",
              isMobile && "pt-[env(safe-area-inset-top)] pr-[env(safe-area-inset-right)] pl-[env(safe-area-inset-left)]",
              // 본문 면의 모서리는 초타원: 같은 반지름이면 덜 둥글어 보여 1.5배로 깎는다(지원하지 않는 브라우저는 둥근 모서리).
              !isMobile && isInset && cn("mt-2 mr-2 squircle rounded-[calc(var(--radius-surface)*1.5)] shadow-surface", !hasBottomBar && "mb-2"))}>
              {children}
            </main>
            {hasBottomBar && <div data-slot="shell-bottom-bar" className="fixed inset-x-0 bottom-0 z-10">{bottomBar}</div>}
            {hasPhoneBar && <PhoneBar {...phoneBar} me={me} current={current} pathname={pathname} />}
            {isMobile && !isFullScreen && !phoneBar && <MobileTabBar space={space} current={current} tabs={tabs} pathname={pathname} />}
          </div>
        </SidebarProvider>
      </PageChromeProvider>
    </TooltipProvider>
  )
}

/** 사이드바 접기 · 펴기 단추. 본문 머리 줄 맨 왼쪽에 선다(Page · PaneFrame이 chrome에서 받아 둔다). */
function SidebarToggle() {
  const { state, toggleSidebar } = useSidebar()
  const isFolded = state === "collapsed"
  const foldLabel = isFolded ? "사이드바 펼치기" : "사이드바 접기"
  return (
    <Button variant="ghost" size="icon-sm" aria-label={foldLabel} aria-expanded={!isFolded} title={`${foldLabel} (Ctrl+B)`} onClick={toggleSidebar}
      className="-ml-1 shrink-0 text-muted-foreground hover:text-foreground">
      {/* 사이드바 그림(PanelLeft): 펼친 동안은 채운 모양, 접힌 동안은 선 모양. */}
      <PanelLeftIcon chosen={!isFolded} />
    </Button>
  )
}

import type { ReactElement, ReactNode } from "react"
import { cn } from "cn"
import { Avatar, AvatarFallback, AvatarImage } from "@/shared/ui/avatar"
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from "@/shared/ui/dropdown-menu"
import { MoreVerticalIcon } from "@/shared/ui/icon"
import { Skeleton } from "@/shared/ui/skeleton"

/**
 * 셸이 보이는 나. 펼친 사이드바는 내 박스(아바타 · 이름 · 소속 · …), 접은 사이드바와 휴대폰 앱 바는 아바타만 그리고,
 * 어느 쪽을 눌러도 같은 내 메뉴(menu: DropdownMenuGroup · DropdownMenuItem들)가 열린다. 읽는 동안은 name 없이 넘긴다.
 */
export type ShellMe = {
  name?: string
  /** 이름 아래 한 줄(소속 · 메일). */
  detail?: string
  picture?: string
  /** 그림이 없을 때의 글자. 없으면 이름 끝 두 글자(한국어 이름의 부르는 이름). */
  initials?: string
  menu: ReactNode
}

const initialsOf = (me: ShellMe) => me.initials ?? me.name?.slice(-2) ?? ""

/** 내 메뉴: trigger(내 박스 · 아바타 단추)를 누르면 연다. */
export function MeMenu({ me, trigger, align = "start" }: { me: ShellMe; trigger: ReactElement; align?: "start" | "end" }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={trigger} />
      <DropdownMenuContent align={align} className="min-w-48">{me.menu}</DropdownMenuContent>
    </DropdownMenu>
  )
}

/** 내 아바타(초타원). 기본 32px, sm은 24px(머리 줄의 아이콘 단추 곁). */
export function MeAvatar({ me, size = "md" }: { me: ShellMe; size?: "sm" | "md" }) {
  // 초타원은 같은 반지름이면 덜 둥글어 보여 조금 크게 깎는다. Avatar의 테두리(after) · 그림 · 글자 면도 같은 모서리로 깎아
  // 안쪽에 선이 하나 더 보이지 않게 한다. 테두리에 혼합(blend)을 쓰지 않는다(초타원과 겹치면 래스터가 크게 늘었다, 1815cf2b).
  const corner = size === "sm" ? "rounded-[0.6875rem]" : "rounded-[0.875rem]"
  return (
    <Avatar className={cn(size === "sm" ? "size-6" : "size-8", "squircle after:squircle", corner, size === "sm" ? "after:rounded-[0.6875rem]" : "after:rounded-[0.875rem]")}>
      {me.picture && <AvatarImage src={me.picture} alt="" className={cn("squircle", corner)} />}
      <AvatarFallback className={cn("squircle bg-secondary font-semibold", corner, size === "sm" ? "text-[0.625rem]" : "text-xs")}>{initialsOf(me)}</AvatarFallback>
    </Avatar>
  )
}

/** 펼친 사이드바의 내 박스: 아바타 · 이름 · 한 줄 · 가로 …, 누르면 내 메뉴. */
export function MeBox({ me }: { me: ShellMe }) {
  return (
    <MeMenu me={me} trigger={
      <button type="button" aria-label={me.name ? `내 메뉴: ${me.name}` : "내 메뉴"}
        className="flex w-full items-center gap-2.5 rounded-xl bg-pressed px-2.5 py-2 text-left outline-none hover:bg-[color-mix(in_srgb,var(--foreground)_10%,transparent)] focus-visible:ring-2 focus-visible:ring-ring">
        <MeAvatar me={me} />
        <span className="flex min-w-0 flex-1 flex-col">
          {me.name ? (
            <>
              <span className="truncate text-sm font-semibold">{me.name}</span>
              {me.detail && <span className="truncate text-xs text-muted-foreground">{me.detail}</span>}
            </>
          ) : (
            <>
              <Skeleton className="my-0.5 h-4 w-16" />
              <Skeleton className="my-0.5 h-3 w-12" />
            </>
          )}
        </span>
        <MoreVerticalIcon className="rotate-90 text-icon-muted" />
      </button>
    } />
  )
}

/** 아바타만 있는 내 메뉴 단추(접은 사이드바 · 머리 줄 · 휴대폰 앱 바). 휴대폰에서는 44px 누름 자리를 둔다. */
export function MeButton({ me, className, align, size = "md" }: { me: ShellMe; className?: string; align?: "start" | "end"; size?: "sm" | "md" }) {
  return (
    <MeMenu me={me} align={align} trigger={
      <button type="button" aria-label={me.name ? `내 메뉴: ${me.name}` : "내 메뉴"}
        className={cn("grid place-items-center rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring max-md:size-11",
          // sm: 곁의 아이콘 단추(28px)와 같은 누름 자리 · 가리킴 면.
          size === "sm" && "size-7 rounded-lg hover:bg-muted", className)}>
        <MeAvatar me={me} size={size} />
      </button>
    } />
  )
}

import { Link } from "@tanstack/react-router"
import { useEffect, useState } from "react"
import { cn } from "cn"
import { Button } from "@/shared/ui/button"
import { Drawer, DrawerClose, DrawerContent, DrawerHeader, DrawerTitle } from "@/shared/ui/drawer"
import { ArrowLeftIcon, FileTextIcon, MoreHorizontalIcon, XIcon } from "@/shared/ui/icon"
import { badgeText, contains, EXACT_LINK, phoneEntriesOf, type NavEntry, type NavSpace } from "./nav"

const tabClass = (isCurrent: boolean) => cn(
  "relative flex h-14 min-w-0 flex-1 flex-col items-center justify-center gap-0.5 text-[0.6875rem] font-medium text-muted-foreground outline-none",
  "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset aria-disabled:text-muted-foreground/50",
  isCurrent && "text-foreground",
)

/**
 * 휴대폰 하단 탭(64rem 미만): 공간 메뉴의 앞 네 곳(tabs로 바꿀 수 있다)과 더보기. 엄지가 닿는 아래에 두고 홈 표시줄을 피한다.
 * 고른 탭과 열린 더보기는 진한 글자와 Bold Duotone이다. 더보기는 나머지 목적지를 바텀시트 한 목록으로 보이고, 하위 공간이면
 * 공간 이름을 제목으로, 맨 위에 돌아가기를 둔다. 아래 줄은 위 항목 아래 들여 쓴 묶음으로 남긴다(위 항목이 탭에 있어도 묶음 머리로 다시 보인다).
 */
export function MobileTabBar({ space, current, tabs: chosenTabs, pathname }: {
  space: NavSpace; current: NavEntry | undefined; tabs?: NavEntry[]
  /** 주소가 바뀌면 더보기를 닫는다. */
  pathname: string
}) {
  const [isMoreOpen, setMoreOpen] = useState(false)
  useEffect(() => setMoreOpen(false), [pathname])
  const entries = phoneEntriesOf(space)
  const tabs = chosenTabs ?? entries.slice(0, 4)
  const more = entries.flatMap(entry => {
    const isTab = tabs.includes(entry)
    const children = entry.children ?? []
    return isTab && children.length === 0 ? [] : [{ entry, isTab }]
  })
  const hasMore = more.length > 0 || Boolean(space.back)
  const isMoreChosen = isMoreOpen || Boolean(current && !tabs.some(tab => contains(tab, current)))
  const title = space.back ? space.title : "더보기"
  const close = () => setMoreOpen(false)
  return (
    <>
      <nav aria-label="주 메뉴" className="flex shrink-0 border-t bg-background pr-[env(safe-area-inset-right)] pb-[env(safe-area-inset-bottom)] pl-[env(safe-area-inset-left)]">
        {tabs.map(entry => <Tab key={`${entry.path}:${entry.label}`} entry={entry} isCurrent={contains(entry, current)} />)}
        {hasMore && (
          <button type="button" aria-haspopup="dialog" aria-expanded={isMoreOpen} onClick={() => setMoreOpen(true)} className={tabClass(isMoreChosen)}>
            <MoreHorizontalIcon chosen={isMoreChosen} className="size-6" />
            <span>더보기</span>
          </button>
        )}
      </nav>
      <Drawer open={isMoreOpen} onOpenChange={setMoreOpen}>
        <DrawerContent>
          <DrawerHeader className="flex-row items-center gap-2 px-3 pt-3 pb-1 text-left">
            <DrawerTitle className="min-w-0 flex-1 truncate px-2 text-left text-base font-semibold">{title}</DrawerTitle>
            <DrawerClose render={<Button variant="ghost" size="icon" aria-label="메뉴 닫기" className="size-11" />}><XIcon className="size-5" /></DrawerClose>
          </DrawerHeader>
          <nav aria-label={title} className="min-h-0 overflow-y-auto px-3 pb-[calc(1.25rem+env(safe-area-inset-bottom))]">
            <ul className="flex flex-col">
              {space.back && (
                <li>
                  <Link to={space.back.path} activeOptions={EXACT_LINK} onClick={close} className={rowClass}>
                    <ArrowLeftIcon className="size-5 shrink-0" />
                    <span className="truncate">{space.back.label}</span>
                  </Link>
                </li>
              )}
              {more.map(({ entry }, index) => {
                const hasChildren = (entry.children?.length ?? 0) > 0
                const previousHasChildren = index > 0 && (more[index - 1].entry.children?.length ?? 0) > 0
                return (
                  // 아래 줄이 있는 묶음은 앞뒤를 가는 선으로 나눈다(접힌 사이드바가 묶음을 선으로 나누는 것과 같다).
                  <li key={`${entry.path}:${entry.label}`} className={cn((hasChildren || previousHasChildren) && (index > 0 || space.back) && "mt-2 border-t pt-2")}>
                    <MoreRow entry={entry} current={current} depth={0} onPick={close} />
                  </li>
                )
              })}
            </ul>
          </nav>
        </DrawerContent>
      </Drawer>
    </>
  )
}

function Tab({ entry, isCurrent }: { entry: NavEntry; isCurrent: boolean }) {
  const Icon = entry.icon ?? FileTextIcon
  const body = (
    <>
      <Icon chosen={isCurrent} className="size-6" />
      <span className="max-w-full truncate px-1">{entry.label}</span>
      {entry.badge ? <span className="absolute top-1.5 left-[calc(50%+0.5rem)] min-w-4 rounded-full bg-foreground px-1 text-[0.625rem] leading-4 text-background tabular-nums">{badgeText(entry.badge)}</span> : null}
    </>
  )
  if (entry.isDisabled) return <span aria-disabled className={tabClass(false)}>{body}</span>
  return <Link to={entry.path} search={entry.search as never} activeOptions={EXACT_LINK} aria-current={isCurrent ? "page" : undefined} className={tabClass(isCurrent)}>{body}</Link>
}

const rowClass = cn(
  "flex h-12 min-w-0 items-center gap-3 rounded-xl px-3 text-base text-muted-foreground outline-none",
  "hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring aria-[current=page]:bg-pressed aria-[current=page]:font-medium aria-[current=page]:text-foreground",
  "aria-disabled:text-muted-foreground/50 aria-disabled:hover:bg-transparent",
)

const INDENT = ["", "pl-11", "pl-19", "pl-27"]

/** 더보기의 줄 하나와 그 아래 줄. 아래 줄은 위 항목의 글자 시작선에 맞춰 들인다(사이드바와 같은 위계). */
export function MoreRow({ entry, current, depth, onPick }: { entry: NavEntry; current: NavEntry | undefined; depth: number; onPick: () => void }) {
  // 같은 메뉴를 다른 곳(휴대폰 메뉴 시트)에서 다시 만들어 넘기기도 하므로, 객체가 아니라 주소로 견준다.
  const isCurrent = !!current && entry.path === current.path && new URLSearchParams(entry.search).toString() === new URLSearchParams(current.search).toString()
  const children = entry.children ?? []
  const mark = entry.media ?? (entry.icon ? <entry.icon chosen={isCurrent} className="size-5 shrink-0" /> : null)
  // 들여쓰기는 단계마다 아이콘(20px) + 간격(12px)이라 위 항목의 글자 시작선에 선다.
  const indent = INDENT[Math.min(depth, INDENT.length - 1)]
  const body = (
    <>
      {mark}
      <span className="min-w-0 flex-1 truncate">{entry.label}</span>
      {entry.badge ? <span className="text-sm text-muted-foreground tabular-nums">{badgeText(entry.badge)}</span> : null}
    </>
  )
  return (
    <>
      {entry.isDisabled
        ? <span aria-disabled className={cn(rowClass, indent)}>{body}</span>
        : (
          <Link to={entry.path} search={entry.search as never} activeOptions={EXACT_LINK} onClick={onPick} aria-current={isCurrent ? "page" : undefined} className={cn(rowClass, indent)}>
            {body}
          </Link>
        )}
      {children.length > 0 && (
        <ul className="flex flex-col">
          {children.map(child => <li key={`${child.path}:${child.label}`}><MoreRow entry={child} current={current} depth={depth + 1} onPick={onPick} /></li>)}
        </ul>
      )}
    </>
  )
}

import { Link } from "@tanstack/react-router"
import { useEffect, useRef, useState } from "react"
import { cn } from "cn"
import { ChevronDownIcon, ChevronUpIcon, FileTextIcon, SearchIcon, type Icon } from "@/shared/ui/icon"
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover"
import { MeButton, type ShellMe } from "./MeMenu"
import { MoreRow } from "./MobileTabBar"
import { badgeText, contains, EXACT_LINK, phoneEntriesOf, type NavEntry, type NavSpace } from "./nav"

/** 휴대폰 메뉴 시트가 머리에서 바꿔 보이는 공간 하나(작업 · 자료): 이름 · 아이콘과 그 공간의 메뉴. */
export type PhoneSpace = { id: string; label: string; icon: Icon; space: NavSpace }

export type PhoneBarProps = {
  /** 늘 같은 앞 칸들(Linear의 Inbox · My issues · Pulse). 공간과 관계없이 그대로다. */
  tabs: NavEntry[]
  /** 메뉴 시트가 머리에서 바꿔 보이는 공간들. */
  spaces: PhoneSpace[]
  /** 지금 주소가 속한 공간(시트가 처음 보이는 것). 없으면 첫 공간. */
  currentSpaceId?: string
  /** 지금 주소의 메뉴 항목(지금 공간의 메뉴에서 찾은 것). 앞 칸이 아니면 끝 칸에 그 아이콘이 선다. */
  current: NavEntry | undefined
  pathname: string
  onSearch?: () => void
  /** 내 사진: 메뉴 시트 머리 오른쪽(Linear의 설정 자리)에서 내 메뉴를 연다. */
  me?: ShellMe
}

/** 유리 면: 반투명 바탕 위로 뒤를 흐린다. 흐림을 못 쓰는 브라우저는 같은 색의 불투명 면이다. */
const GLASS = "border bg-background shadow-md supports-backdrop-filter:bg-background/55 supports-backdrop-filter:backdrop-blur-xl"

/** 위아래 꺾쇠 한 쌍(⇕): 끝 칸이 다른 곳으로 바꾸는 단추임을 보인다. */
function Selector({ className }: { className?: string }) {
  return (
    <span aria-hidden className={cn("flex flex-col items-center text-icon-muted [&_svg]:size-2.5", className)}>
      <ChevronUpIcon className="-mb-0.5" />
      <ChevronDownIcon className="-mt-0.5" />
    </span>
  )
}

const slotClass = (isCurrent: boolean) => cn(
  "relative flex h-11 min-w-0 flex-1 items-center justify-center gap-0.5 rounded-full text-muted-foreground outline-none transition-colors",
  "focus-visible:ring-2 focus-visible:ring-ring",
  isCurrent && "bg-pressed text-foreground",
)

/**
 * 휴대폰 하단(Linear 모바일): 화면 아래에서 띄운 둥근 유리 막대와 그 옆 검색 원. 막대의 앞 칸은 늘 같고, 끝 칸은 메뉴 시트를
 * 연다. 시트 머리는 공간 이름 ⇕(누르면 다른 공간의 메뉴로 바뀐다), 그 아래는 그 공간의 메뉴(데스크톱 사이드바와 같은 것)다.
 * 시트에서 고른 곳이 앞 칸이 아니면 끝 칸에 그 아이콘이 남아, 지금 자리와 바꾸는 단추가 한 칸에 보인다.
 * 페이지는 막대 몫(--phone-bar-space)을 아래에 비워 마지막 줄이 막대에 가리지 않는다(AppShell이 정한다).
 */
export function PhoneBar({ tabs, spaces, currentSpaceId, current, pathname, onSearch, me }: PhoneBarProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [shownId, setShownId] = useState(currentSpaceId ?? spaces[0]?.id)
  useEffect(() => setIsOpen(false), [pathname])
  useEffect(() => { if (isOpen) setShownId(currentSpaceId ?? spaces[0]?.id) }, [isOpen, currentSpaceId, spaces])
  const at = (path: string) => pathname === path || pathname.startsWith(`${path}/`)
  const onTab = tabs.some(tab => at(tab.path))
  const shown = spaces.find(each => each.id === shownId) ?? spaces[0]
  const next = spaces[(spaces.indexOf(shown!) + 1) % spaces.length]
  const Place = !onTab && current?.icon ? current.icon : undefined
  const close = () => setIsOpen(false)
  // 메뉴 시트는 앞 칸 묶음(막대) 자리에서 그 너비로 펼쳐져 막대를 덮는다(Linear 모바일처럼, 막대 위로 따로 뜨지 않는다).
  const bar = useRef<HTMLElement>(null)
  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-0 z-30 flex items-center gap-3 px-4 pr-[max(1rem,env(safe-area-inset-right))] pb-[calc(0.75rem+env(safe-area-inset-bottom))] pl-[max(1rem,env(safe-area-inset-left))]">
      <nav ref={bar} aria-label="주 메뉴" className={cn("phone-bar pointer-events-auto flex h-14 min-w-0 flex-1 items-center gap-1 rounded-full p-1.5 transition-opacity", GLASS, isOpen && "opacity-0")}>
        {tabs.map(tab => {
          const isCurrent = at(tab.path)
          const TabIcon = tab.icon ?? FileTextIcon
          return (
            <Link key={tab.path} to={tab.path} search={tab.search as never} activeOptions={EXACT_LINK} aria-label={tab.label}
              aria-current={isCurrent ? "page" : undefined} className={slotClass(isCurrent)}>
              <TabIcon chosen={isCurrent} className="size-6" />
              {tab.badge ? <span className="absolute top-1 left-[calc(50%+0.375rem)] min-w-4 rounded-full bg-foreground px-1 text-[0.625rem] leading-4 text-background tabular-nums">{badgeText(tab.badge)}</span> : null}
            </Link>
          )
        })}
        <Popover open={isOpen} onOpenChange={setIsOpen}>
          <PopoverTrigger render={
            <button type="button" aria-label={Place ? `${current?.label}, 메뉴 열기` : "메뉴 열기"} className={slotClass(!onTab || isOpen)}>
              {Place && <Place chosen className="size-6" />}
              <Selector className={Place ? undefined : "[&_svg]:size-3.5"} />
            </button>
          } />
          <PopoverContent anchor={bar} side="top" align="start" sideOffset={-56} className={cn("w-(--anchor-width) gap-1 rounded-[1.75rem] p-2", GLASS)}>
            <div className="flex items-center gap-1">
              {shown && (
                <button type="button" onClick={() => next && setShownId(next.id)} aria-label={next ? `${shown.label} 메뉴, ${next.label}로 바꾸기` : `${shown.label} 메뉴`}
                  className="flex h-12 min-w-0 flex-1 items-center gap-3 rounded-xl px-3 text-base font-semibold outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring">
                  <shown.icon chosen className="size-5 shrink-0" />
                  <span className="min-w-0 truncate">{shown.label}</span>
                  <Selector />
                </button>
              )}
              {me && <MeButton me={me} align="end" className="ml-auto shrink-0" />}
            </div>
            <div aria-hidden className="mx-3 border-t" />
            <nav aria-label={shown ? `${shown.label} 메뉴` : "메뉴"} className="max-h-[60dvh] overflow-y-auto">
              <ul className="flex flex-col">
                {shown && phoneEntriesOf(shown.space).map(entry => (
                  <li key={`${entry.path}:${entry.label}`}><MoreRow entry={entry} current={current && contains(entry, current) ? current : undefined} depth={0} onPick={close} /></li>
                ))}
              </ul>
            </nav>
          </PopoverContent>
        </Popover>
      </nav>
      {onSearch && (
        <button type="button" aria-label="검색" onClick={onSearch}
          className={cn("phone-bar-search pointer-events-auto grid size-14 shrink-0 place-items-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring", GLASS)}>
          <SearchIcon className="size-6" />
        </button>
      )}
    </div>
  )
}

import { Collapsible } from "@base-ui/react/collapsible"
import { Link } from "@tanstack/react-router"
import { useEffect, useState, type ReactNode } from "react"
import { cn } from "cn"
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from "@/shared/ui/dropdown-menu"
import { ArrowLeftIcon, ChevronDownIcon, MoreHorizontalIcon, SquareArrowOutUpRightIcon } from "@/shared/ui/icon"
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupAction, SidebarGroupContent, SidebarHeader,
  SidebarMenu, SidebarMenuAction, SidebarMenuBadge, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub, SidebarMenuSubButton,
  SidebarMenuSubItem, SidebarSeparator, useSidebar,
} from "@/shared/ui/sidebar"
import { MeBox, MeButton, type ShellMe } from "./MeMenu"
import { badgeText, contains, entriesOf, EXACT_LINK, type NavEntry, type NavSpace } from "./nav"

export type ShellLayout = "inset" | "split"
/** 'all'은 아래 줄 묶음을 모두 펼친다(메뉴가 짧은 업무 앱). 'current'는 지금 자리의 묶음만(묶음이 많은 문서 사이트). */
export type OpenGroups = "all" | "current"
/** 접힌 사이드바에도 그리는 자리는 접힘 여부를 받는다. */
export type FoldSlot = ReactNode | ((isFolded: boolean) => ReactNode)

export const slot = (value: FoldSlot | undefined, isFolded: boolean) => (typeof value === "function" ? value(isFolded) : value)
const keyOf = (entry: NavEntry) => (entry.search ? `${entry.path}?${new URLSearchParams(entry.search)}` : entry.path)

/** 지금 자리까지 내려가는 묶음들(위에서부터). 모두 열어 지금 자리가 보이게 한다. */
function trailTo(list: readonly NavEntry[], current: NavEntry | undefined): string[] {
  for (const entry of list) {
    if (!entry.children?.length || !contains(entry, current)) continue
    return [keyOf(entry), ...trailTo(entry.children, current)]
  }
  return []
}

type Groups = { isOpen: (entry: NavEntry) => boolean | undefined; setOpen: (entry: NavEntry, isOpen: boolean) => void }

/**
 * 접고 펴는 칸의 움직임: Base UI가 재 둔 높이(--collapsible-panel-height)로 200ms 동안 줄고 는다. 움직임을 줄이는 설정이면 바로 바뀐다.
 */
const PANEL = "h-(--collapsible-panel-height) overflow-hidden [interpolate-size:allow-keywords] transition-[height] duration-200 ease-out data-ending-style:h-0 data-starting-style:h-0 motion-reduce:transition-none"

const FOLDS_KEY = "app-shell:folds"

/**
 * 사용자가 접어 둔 것(묶음 머리 · 아래 줄 있는 항목)의 기록: 접은 것만 남기고, 새로고침해도 그대로다(Linear). 이 브라우저에 남는다.
 * 저장할 수 없으면(사생활 보호 창 등) 이번 화면에만 반영한다.
 */
function useFolds() {
  const [folded, setFolded] = useState<ReadonlySet<string>>(() => {
    try { return new Set(JSON.parse(localStorage.getItem(FOLDS_KEY) ?? "[]") as string[]) } catch { return new Set() }
  })
  const setOpen = (id: string, isOpen: boolean) => setFolded(current => {
    const next = new Set(current)
    if (isOpen) next.delete(id)
    else next.add(id)
    try { localStorage.setItem(FOLDS_KEY, JSON.stringify([...next])) } catch { /* 이번 화면에만 */ }
    return next
  })
  return { isOpen: (id: string) => !folded.has(id), setOpen }
}
type Folds = ReturnType<typeof useFolds>

/**
 * 'current'의 펼침 상태. 다른 묶음 안으로 옮겨 가면 그 묶음도 펼치고, 사용자가 연 묶음은 그대로 둔다.
 * 'all'은 처음에 모두 펼치고, 사용자가 접은 것을 기억한다(useFolds).
 */
function useGroups(mode: OpenGroups, entries: readonly NavEntry[], current: NavEntry | undefined, folds: Folds): Groups {
  const trail = trailTo(entries, current).join("\n")
  const [open, setOpenKeys] = useState(() => new Set(trail ? trail.split("\n") : []))
  useEffect(() => {
    if (!trail) return
    setOpenKeys(keys => (trail.split("\n").every(key => keys.has(key)) ? keys : new Set([...keys, ...trail.split("\n")])))
  }, [trail])
  if (mode === "all") return { isOpen: entry => folds.isOpen(`entry:${keyOf(entry)}`), setOpen: (entry, isOpen) => folds.setOpen(`entry:${keyOf(entry)}`, isOpen) }
  return {
    isOpen: entry => open.has(keyOf(entry)),
    setOpen: (entry, isOpen) => setOpenKeys(keys => {
      const next = new Set(keys)
      if (isOpen) next.add(keyOf(entry))
      else next.delete(keyOf(entry))
      return next
    }),
  }
}

export type ShellSidebarProps = {
  space: NavSpace
  /**
   * 메뉴 아래 "관리" 이름표 묶음(권한이 있을 때의 관리 화면). 관리는 다른 공간이라 줄 끝에 옮겨 가는 표시를 둔다.
   */
  adminEntries?: NavEntry[]
  current: NavEntry | undefined
  /** 머리의 로고 · 이름(홈 링크는 앱이 감싼다). 접힌 사이드바는 표시만 남긴다. 셸의 머리 줄이 있으면 그쪽에 두고 비운다. */
  brand?: FoldSlot
  /** 머리 줄 오른쪽 작은 도구(전역 검색). 접히면 로고 아래로 내려간다. */
  headerTools?: ReactNode
  me?: ShellMe
  /** 바닥 왼쪽(릴리스 · 환경). 접기 단추는 셸이 둔다. */
  footer?: FoldSlot
  layout: ShellLayout
  openGroups: OpenGroups
  /** 화면 아래에 줄(에이전트 줄)이 있다: 사이드바도 그만큼 짧아져, 바닥(접기 · 버전)이 본문 면 바닥과 같은 높이에 선다. */
  isAboveBar?: boolean
}

/**
 * 데스크톱 사이드바. 머리: 로고 · 도구, 그 아래 내 박스. 몸: 공간의 메뉴(하위 공간이면 맨 위에 ← 공간 이름),
 * 아래 줄이 있는 항목은 오른쪽 끝 꺾쇠로 접고 편다. 바닥: 앱의 한 줄과 접기. 접으면 아이콘만 남고 묶음 사이를 가는 선으로 나눈다.
 */
export function ShellSidebar({ space, current, brand, headerTools, me, footer, adminEntries, layout, openGroups, isAboveBar }: ShellSidebarProps) {
  const { state } = useSidebar()
  const isFolded = state === "collapsed"
  const folds = useFolds()
  const groups = useGroups(openGroups, entriesOf(space), current, folds)
  return (
    <Sidebar collapsible="icon" variant={layout === "inset" ? "inset" : "sidebar"} aria-label="주 메뉴"
      className={isAboveBar ? "h-[calc(100svh-2.5rem)]" : undefined}>
      {(brand || headerTools || me) && <SidebarHeader className={cn("gap-3 px-3 group-data-[collapsible=icon]:px-2", layout === "inset" ? "pt-3" : "pt-0")}>
        {/* split은 머리 줄을 페이지 머리 줄(52px)과 같은 선에 둔다. */}
        <div className={cn("flex items-center justify-between gap-2 group-data-[collapsible=icon]:h-auto group-data-[collapsible=icon]:flex-col",
          layout === "inset" ? "h-8" : "h-13 group-data-[collapsible=icon]:pt-3")}>
          <div className="flex min-w-0 flex-1 items-center gap-1.5 group-data-[collapsible=icon]:flex-none group-data-[collapsible=icon]:flex-col">{slot(brand, isFolded)}</div>
          {headerTools && <div className="flex shrink-0 items-center gap-1 group-data-[collapsible=icon]:flex-col">{headerTools}</div>}
        </div>
        {me && (isFolded ? <MeButton me={me} className="mx-auto" /> : <MeBox me={me} />)}
      </SidebarHeader>}
      {/* 스크롤 막대 자리를 늘 비워 둔다: 메뉴가 길어져 막대가 생겼다 사라질 때 항목이 좌우로 흔들리지 않게(본문처럼). 막대는 가늘게. */}
      <SidebarContent className="px-1 [scrollbar-gutter:stable] [scrollbar-width:thin] group-data-[collapsible=icon]:[scrollbar-gutter:auto]">
        {space.back && (
          <SidebarGroup className="py-1">
            <SidebarMenu>
              <SidebarMenuItem>
                <SidebarMenuButton tooltip={space.back.label} aria-label={`${space.back.label}: ${space.title}`}
                  render={<Link to={space.back.path} activeOptions={EXACT_LINK} />} className="font-semibold">
                  <ArrowLeftIcon />
                  <span>{space.title}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            </SidebarMenu>
          </SidebarGroup>
        )}
        {space.sections.map((section, index) => {
          const content = (
            <SidebarGroupContent>
              <SidebarMenu className="gap-0.5">
                {section.entries.map(entry => <TopItem key={keyOf(entry)} entry={entry} current={current} groups={groups} />)}
              </SidebarMenu>
            </SidebarGroupContent>
          )
          // 이름 있는 묶음의 머리(Linear의 Your teams ▾)는 누르면 그 묶음을 접고 펴기만 한다. 접은 사이드바는 머리 없이 늘 펼친다.
          if (section.isHeaderHidden || section.isLabel || isFolded) {
            return (
              <SidebarGroup key={section.title} className="group/section py-1">
                {isFolded && (index > 0 || space.back) && <SidebarSeparator className="mx-0 mb-1 data-horizontal:w-7" />}
                {/* 이름표: 접는 줄과 같은 자리 · 글자, 꺾쇠와 누름 없이. */}
                {section.isLabel && !section.isHeaderHidden && !isFolded && (
                  <div className={cn("flex h-8 items-center px-2 text-sm text-muted-foreground", section.action && "pr-8")}>{section.title}</div>
                )}
                {section.isLabel && section.action && !isFolded && (
                  <SidebarGroupAction aria-label={section.action.label} title={section.action.label} onClick={section.action.onClick}
                    className="top-2.5 right-2 opacity-0 group-hover/section:opacity-100 focus-visible:opacity-100">
                    <section.action.icon />
                  </SidebarGroupAction>
                )}
                {content}
              </SidebarGroup>
            )
          }
          return (
            <Collapsible.Root key={section.title} open={folds.isOpen(`section:${space.id}:${section.title}`)}
              onOpenChange={isOpen => folds.setOpen(`section:${space.id}:${section.title}`, isOpen)} render={<SidebarGroup className="group/section py-1" />}>
              <Collapsible.Trigger className={cn("group/head flex h-8 w-full items-center gap-1.5 rounded-[0.625rem] px-2 text-left text-sm text-muted-foreground outline-none",
                "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 focus-visible:ring-sidebar-ring", section.action && "pr-8")}>
                <span className="truncate">{section.title}</span>
                <ChevronDownIcon className="size-3 shrink-0 text-icon-muted transition-transform group-not-data-panel-open/head:-rotate-90" />
              </Collapsible.Trigger>
              {section.action && (
                <SidebarGroupAction aria-label={section.action.label} title={section.action.label} onClick={section.action.onClick}
                  className="top-2.5 right-2 opacity-0 group-hover/section:opacity-100 focus-visible:opacity-100">
                  <section.action.icon />
                </SidebarGroupAction>
              )}
              <Collapsible.Panel className={PANEL}>{content}</Collapsible.Panel>
            </Collapsible.Root>
          )
        })}
        {adminEntries && adminEntries.length > 0 && (
          // 메뉴 묶음들 아래 "관리" 이름표(메뉴 묶음 이름표와 같은 모양). 항목은 다른 공간으로 옮겨 가므로 줄 끝에 ↗.
          <SidebarGroup className="py-1">
            {isFolded ? <SidebarSeparator className="mx-0 mb-1 data-horizontal:w-7" />
              : <div className="flex h-8 items-center px-2 text-sm text-muted-foreground">관리</div>}
            <SidebarGroupContent>
              <SidebarMenu className="gap-0.5">
                {adminEntries.map(entry => <TopItem key={keyOf(entry)} entry={entry} current={current} groups={groups}
                  trailing={<SquareArrowOutUpRightIcon aria-label="다른 공간으로 이동" className="ml-auto size-3.5 shrink-0 text-icon-muted" />} />)}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        )}
      </SidebarContent>
      {footer ? <SidebarFooter className="flex-row items-center px-3 pb-2 group-data-[collapsible=icon]:flex-col group-data-[collapsible=icon]:justify-center">
        <div className="flex min-w-0 items-center gap-1 text-xs text-muted-foreground group-data-[collapsible=icon]:flex-col">{slot(footer, isFolded)}</div>
      </SidebarFooter> : null}
    </Sidebar>
  )
}

/** 항목의 그림: media(프로젝트 표식)가 먼저, 없으면 아이콘(지금 자리면 Bold Duotone). */
function EntryMark({ entry, isCurrent }: { entry: NavEntry; isCurrent: boolean }) {
  if (entry.media) return <>{entry.media}</>
  return entry.icon ? <entry.icon chosen={isCurrent} /> : null
}

const linkOf = (entry: NavEntry) => (entry.isDisabled ? undefined : <Link to={entry.path} search={entry.search as never} activeOptions={EXACT_LINK} />)

/** 아래 줄을 접고 펴는 꺾쇠(오른쪽 끝). 접힌 동안 오른쪽을 가리킨다. */
function GroupTrigger({ entry }: { entry: NavEntry }) {
  return (
    <Collapsible.Trigger aria-label={`${entry.label} 아래 메뉴`} render={<SidebarMenuAction />}
      className="[&>svg]:transition-transform not-data-panel-open:[&>svg]:-rotate-90">
      <ChevronDownIcon />
    </Collapsible.Trigger>
  )
}

/**
 * 최상위 항목. 아래 줄이 지금 자리여도 함께 칠해 어느 묶음 안인지 보인다. 아래 줄이 있으면 처음에 펼친다
 * ('current'는 지금 자리의 묶음만).
 */
function TopItem({ entry, current, groups, trailing }: { entry: NavEntry; current: NavEntry | undefined; groups: Groups; trailing?: ReactNode }) {
  const isCurrent = contains(entry, current)
  const children = entry.children ?? []
  const { state } = useSidebar()
  if (entry.isGroup && children.length > 0 && state !== "collapsed") return <GroupItem entry={entry} current={current} groups={groups} />
  // 할 일 항목(탐색): 이동하지 않고 그 일을 한다.
  if (entry.onSelect) return <SidebarMenuItem>
    <SidebarMenuButton tooltip={entry.label} onClick={entry.onSelect}>
      <EntryMark entry={entry} isCurrent={false} />
      <span>{entry.label}</span>
      {trailing}
    </SidebarMenuButton>
  </SidebarMenuItem>
  const button = (
    <SidebarMenuButton isActive={isCurrent} tooltip={entry.label} disabled={entry.isDisabled}
      aria-current={entry === current ? "page" : undefined} render={linkOf(entry)}>
      <EntryMark entry={entry} isCurrent={isCurrent} />
      <span>{entry.label}</span>
      {trailing}
    </SidebarMenuButton>
  )
  const badge = entry.badge ? <SidebarMenuBadge className={cn(children.length > 0 && "right-7")}>{badgeText(entry.badge)}</SidebarMenuBadge> : null
  if (children.length === 0) return <SidebarMenuItem>{button}{badge}</SidebarMenuItem>
  return (
    <Collapsible.Root defaultOpen open={groups.isOpen(entry)} onOpenChange={isOpen => groups.setOpen(entry, isOpen)} render={<SidebarMenuItem />}>
      {button}
      {badge}
      <GroupTrigger entry={entry} />
      <Collapsible.Panel className={PANEL}>
        <SidebarMenuSub>
          {children.map(child => <SubItem key={keyOf(child)} entry={child} current={current} groups={groups} />)}
        </SidebarMenuSub>
      </Collapsible.Panel>
    </Collapsible.Root>
  )
}

/**
 * 묶음 머리(Linear의 팀 줄): 누르면 아래 줄을 접고 펴기만 한다. 이름 뒤 작은 꺾쇠가 접힘을 보인다. 지금 자리가 그 안이어도
 * 머리는 칠하지 않는다(아래 줄이 칠해진다).
 */
function GroupItem({ entry, current, groups }: { entry: NavEntry; current: NavEntry | undefined; groups: Groups }) {
  return (
    <Collapsible.Root defaultOpen open={groups.isOpen(entry)} onOpenChange={isOpen => groups.setOpen(entry, isOpen)} render={<SidebarMenuItem />}>
      <Collapsible.Trigger render={<SidebarMenuButton tooltip={entry.label} />} className={cn("group/group", entry.menu && "pr-8")}>
        <EntryMark entry={entry} isCurrent={false} />
        <span>{entry.label}</span>
        <ChevronDownIcon className="size-3! text-icon-muted transition-transform group-not-data-panel-open/group:-rotate-90" />
      </Collapsible.Trigger>
      {entry.menu && (
        <DropdownMenu>
          <DropdownMenuTrigger render={<SidebarMenuAction showOnHover aria-label={`${entry.label} 메뉴`} />}><MoreHorizontalIcon /></DropdownMenuTrigger>
          <DropdownMenuContent side="right" align="start" className="min-w-52">{entry.menu}</DropdownMenuContent>
        </DropdownMenu>
      )}
      <Collapsible.Panel className={PANEL}>
        <SidebarMenuSub>
          {(entry.children ?? []).map(child => <SubItem key={keyOf(child)} entry={child} current={current} groups={groups} />)}
        </SidebarMenuSub>
      </Collapsible.Panel>
    </Collapsible.Root>
  )
}

/** 아래 줄. 다시 아래 줄이 있으면 같은 꺾쇠로 접고, 그 안의 줄은 한 단계 더 들인다. */
function SubItem({ entry, current, groups }: { entry: NavEntry; current: NavEntry | undefined; groups: Groups }) {
  const isCurrent = entry === current
  const children = entry.children ?? []
  const button = (
    <SidebarMenuSubButton isActive={isCurrent} aria-current={isCurrent ? "page" : undefined} aria-disabled={entry.isDisabled || undefined}
      render={linkOf(entry) ?? <span />} className={cn(children.length > 0 && "pr-8", entry.badge && "pr-8")}>
      <EntryMark entry={entry} isCurrent={isCurrent} />
      <span>{entry.label}</span>
    </SidebarMenuSubButton>
  )
  const badge = entry.badge ? <SidebarMenuBadge className={cn("top-1", children.length > 0 && "right-7")}>{badgeText(entry.badge)}</SidebarMenuBadge> : null
  if (children.length === 0) return <SidebarMenuSubItem>{button}{badge}</SidebarMenuSubItem>
  return (
    <Collapsible.Root defaultOpen open={groups.isOpen(entry)} onOpenChange={isOpen => groups.setOpen(entry, isOpen)} render={<SidebarMenuSubItem />}>
      {button}
      {badge}
      <GroupTrigger entry={entry} />
      <Collapsible.Panel className={PANEL}>
        <SidebarMenuSub className="mr-0 pr-0">
          {children.map(child => <SubItem key={keyOf(child)} entry={child} current={current} groups={groups} />)}
        </SidebarMenuSub>
      </Collapsible.Panel>
    </Collapsible.Root>
  )
}

import { useEffect, useRef, useState, type FocusEvent, type KeyboardEvent, type PointerEvent } from "react"
import { cn } from "cn"

/** 손잡이의 지금 상태: 가리키는 중이면 hover, 끄는 중이거나 키보드 초점이면 active. */
export type HandleEdge = "idle" | "hover" | "active"

const STEP = 16

/** 루트 글자 크기의 배율. 큰 화면(1920px 이상)은 루트를 키우므로 화면 px를 기준 px로 되돌릴 때 쓴다. */
const rootScale = () => parseFloat(getComputedStyle(document.documentElement).fontSize) / 16 || 1

/**
 * 사이드바 오른쪽 가장자리의 너비 손잡이(Linear처럼 가장자리를 끈다). 끌거나, 초점을 두고 ← → (Shift는 4배) · Home · End.
 * inset 바닥에는 선이 없으므로 평소에는 보이지 않고, 가리킬 때 · 끄는 동안 · 키보드 초점에서만 선이 선다.
 * 값은 루트 16px 기준 px이다. 사이드바 너비를 rem으로 두므로 큰 화면에서 루트가 커지면 끄는 거리도 그만큼 나눈다.
 * onEdgeChange를 받으면(inset) 선을 손잡이에 긋지 않고 상태만 알린다: 셸이 본문 면의 왼쪽 가장자리에 표시를 둔다(창 높이 전체에 선이
 * 서지 않게).
 * (PaneResizeHandle은 늘 선을 그리는 칸 구분선이라 따로 둔다.)
 */
export function SidebarResizeHandle({ value, min, max, onChange, onDraggingChange, onEdgeChange }: {
  value: number; min: number; max: number; onChange: (width: number) => void; onDraggingChange: (isDragging: boolean) => void
  onEdgeChange?: (edge: HandleEdge) => void
}) {
  const start = useRef<{ x: number; width: number; scale: number } | null>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [isHovered, setIsHovered] = useState(false)
  const [isFocusVisible, setIsFocusVisible] = useState(false)
  const edge: HandleEdge = isDragging || isFocusVisible ? "active" : isHovered ? "hover" : "idle"
  useEffect(() => { onEdgeChange?.(edge) }, [edge, onEdgeChange])
  const resize = (width: number) => onChange(Math.round(Math.min(max, Math.max(min, width))))
  const drag = (next: boolean) => {
    setIsDragging(next)
    onDraggingChange(next)
  }

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return
    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    start.current = { x: event.clientX, width: value, scale: rootScale() }
    drag(true)
  }
  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const at = start.current
    if (at) resize(at.width + (event.clientX - at.x) / at.scale)
  }
  const onPointerEnd = () => {
    start.current = null
    drag(false)
  }
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? STEP * 4 : STEP
    const next = { ArrowLeft: value - step, ArrowRight: value + step, Home: min, End: max }[event.key]
    if (next === undefined) return
    event.preventDefault()
    resize(next)
  }

  return (
    <div role="separator" aria-orientation="vertical" aria-label="사이드바 너비" aria-valuenow={value} aria-valuemin={min} aria-valuemax={max}
      tabIndex={0} data-dragging={isDragging || undefined}
      onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerEnd} onPointerCancel={onPointerEnd} onKeyDown={onKeyDown}
      onPointerEnter={() => setIsHovered(true)} onPointerLeave={() => setIsHovered(false)}
      onFocus={(event: FocusEvent<HTMLDivElement>) => setIsFocusVisible(event.currentTarget.matches(":focus-visible"))} onBlur={() => setIsFocusVisible(false)}
      className="group/handle relative z-20 -mx-1 flex w-2 shrink-0 cursor-col-resize touch-none justify-center outline-none">
      {!onEdgeChange && <span className={cn("w-0.5 rounded-full transition-[width,background-color] group-hover/handle:bg-border",
        "group-focus-visible/handle:w-1 group-focus-visible/handle:bg-ring group-data-dragging/handle:bg-ring")} />}
    </div>
  )
}

import type { ReactNode } from "react"
import type { Icon } from "@/shared/ui/icon"

/**
 * 메뉴의 목적지 하나. children은 펼치는 아래 줄(별표한 프로젝트 · 저장한 뷰 · 문서 묶음)이며 몇 단계든 된다.
 * 같은 주소의 다른 뷰(?view=)처럼 주소만으로 지금 자리를 가릴 수 없으면 isCurrent로 직접 정한다.
 */
export type NavEntry = {
  path: string
  /** 같은 페이지의 다른 조건(?view=). 링크에 붙고, 지금 자리 판단에는 쓰지 않는다. */
  search?: Record<string, string>
  label: string
  /** 아래 줄은 아이콘을 생략할 수 있다(위 항목 아래에 들여 쓴다). */
  icon?: Icon
  /** 아이콘 대신 그릴 것(프로젝트 표식). */
  media?: ReactNode
  /** 옆의 수(읽지 않은 알림). 99를 넘으면 99+. */
  badge?: number
  isDisabled?: boolean
  /** 지금 자리를 직접 정한다. 없으면 주소의 가장 긴 접두사로 찾는다. */
  isCurrent?: boolean
  /** 휴대폰 하단 탭 · 더보기에 넣지 않는다(앱 바 도구가 같은 곳을 연다: 알림함). */
  isPhoneHidden?: boolean
  /** 묶음 머리(Linear의 팀): 누르면 이동하지 않고 아래 줄을 접고 편다. 접은 사이드바에서는 path로 간다. */
  isGroup?: boolean
  /** 이동 대신 할 일(탐색: 전체 검색 창 열기). 있으면 링크가 아니라 단추로 그리고, 지금 자리로 칠하지 않는다. */
  onSelect?: () => void
  /** 줄 끝 … 메뉴의 항목들(DropdownMenuItem). 가리키거나 초점이 오면 보인다(Linear의 팀 메뉴). */
  menu?: ReactNode
  children?: NavEntry[]
}

/** 묶음 머리 끝의 작은 단추(Linear의 Your teams 옆 +). 가리키거나 초점이 오면 보인다. */
export type NavSectionAction = { label: string; icon: Icon; onClick: () => void }

/** 이름 있는 묶음. 첫 묶음처럼 이름이 필요 없으면 isHeaderHidden. */
/** isLabel: 이름은 접고 펴는 줄이 아니라 그냥 이름표다(누르지 않는다). */
export type NavSection = { title: string; isHeaderHidden?: boolean; isLabel?: boolean; action?: NavSectionAction; entries: NavEntry[] }

/**
 * 화면에 보이는 메뉴 한 벌. 주 메뉴, 또는 주 메뉴에서 연 하위 공간(내 계정 · 프로젝트 · 관리)이 주 메뉴를 대체하고
 * back으로 돌아간다. 어느 공간인지는 앱이 주소로 정해 넘긴다.
 */
export type NavSpace = { id: string; title: string; back?: { label: string; path: string }; sections: NavSection[] }

/** 공간의 최상위 항목들(묶음 순서대로). */
export const entriesOf = (space: NavSpace) => space.sections.flatMap(section => section.entries)

/** 모든 단계의 항목을 위에서부터 한 줄로. */
export const flattenEntries = (list: readonly NavEntry[]): NavEntry[] => list.flatMap(entry => [entry, ...flattenEntries(entry.children ?? [])])

const baseOf = (path: string) => path.split("?")[0]

/**
 * 주소에 해당하는 항목: isCurrent를 정한 항목은 그것을 따르고, 나머지는 항목 주소이거나 그 아래인 것 중 가장 긴 것.
 * 같은 주소의 뷰 줄(search가 있는 줄)은 접두사 판단에서 빼 위 항목이 지금 자리가 된다.
 */
export function currentEntry(space: NavSpace, pathname: string): NavEntry | undefined {
  const all = flattenEntries(entriesOf(space))
  const chosen = all.find(entry => entry.isCurrent)
  if (chosen) return chosen
  return all
    .filter(entry => entry.isCurrent === undefined && !entry.search)
    .filter(entry => pathname === baseOf(entry.path) || pathname.startsWith(`${baseOf(entry.path)}/`))
    // 가장 긴 주소가 지금 자리다. 묶음 줄과 그 아래 첫 항목이 같은 주소면(프로젝트 줄과 그 '업무') 아래 항목이 지금 자리다:
    // 묶음 줄이 이기면 아래 항목이 고른 표시를 받지 못한다.
    .sort((a, b) => baseOf(b.path).length - baseOf(a.path).length || Number(!!a.children?.length) - Number(!!b.children?.length))[0]
}

/** entry나 그 아래 어딘가가 target인지. 위 항목을 함께 칠하고, 탭이 지금 자리인지 볼 때 쓴다. */
export const contains = (entry: NavEntry, target: NavEntry | undefined): boolean =>
  !!target && (entry === target || (entry.children ?? []).some(child => contains(child, target)))

/** 휴대폰 탭과 더보기에 둘 수 있는 최상위 항목. */
export const phoneEntriesOf = (space: NavSpace) => entriesOf(space).filter(entry => !entry.isPhoneHidden)

export const badgeText = (count: number) => (count > 99 ? "99+" : String(count))

/**
 * 메뉴 링크의 activeOptions. TanStack Link는 기본으로 주소의 접두사가 같으면 스스로 aria-current="page"를 단다. 그러면 위 항목과
 * 지금 항목이 함께 "지금 페이지"로 읽히므로, 링크는 주소와 검색 값이 똑같을 때만 스스로 달고 나머지는 셸이 정한다.
 */
export const EXACT_LINK = { exact: true, includeSearch: true } as const
